    { id="05-d11", start=nil, name="黑石深淵", short=nil, visit=nil, map=1427, lv={52, 60}, video=nil, test=nil, alt=nil, when=nil, tips={{k="動線", text="在鐵爐堡能飛就飛瑟銀哨塔，從灼熱峽谷南端進黑石山。飛不到就從丹莫洛東側進洛克莫丹，往南進荒蕪之地，再往西繞開卡加斯進灼熱峽谷。→在冬泉谷組到隊，可飛奧伯丁。飛不到就循木喉要塞原路回費伍德，經梣谷走到黑海岸的奧伯丁。搭船去暴風城，再飛瑟銀哨塔。沒開東部飛點就從暴風城走艾爾文森林、赤脊山，沿湖畔鎮北路進燃燒平原，再往西進黑石山。→續燃燒平原主線就從黑石山南門出去，沿大路往東到摩根的崗哨。→若正要回羽月要塞，爐石綁阿斯特蘭納且可用就先爐回去。否則從燃燒平原經赤脊山、艾爾文森林到暴風城港搭船回奧伯丁。回到卡林多再飛羽月要塞。沒有航線就從梣谷經石爪山脈、淒涼之地進菲拉斯，到西岸碼頭搭船上島。", s={{"在鐵爐堡能飛就飛瑟銀哨塔，從灼熱峽谷南端進黑石山"}, {"飛不到就從丹莫洛東側進洛克莫丹，往南進荒蕪之地，再往西繞開卡加斯進灼熱峽谷"}, {"→在冬泉谷組到隊，可飛奧伯丁"}, {"飛不到就循木喉要塞原路回費伍德，經梣谷走到黑海岸的奧伯丁"}, {"搭船去暴風城，再飛瑟銀哨塔"}, {"沒開東部飛點就從暴風城走艾爾文森林、赤脊山，沿湖畔鎮北路進燃燒平原，再往西進黑石山"}, {"→續燃燒平原主線就從黑石山南門出去，沿大路往東到摩根的崗哨"}, {"→若正要回羽月要塞，爐石綁阿斯特蘭納且可用就先爐回去"}, {"否則從燃燒平原經赤脊山、艾爾文森林到暴風城港搭船回奧伯丁"}, {"回到卡林多再飛羽月要塞"}, {"沒有航線就從梣谷經石爪山脈、淒涼之地進菲拉斯，到西岸碼頭搭船上島"}}}}, dungeon=true, grind=nil, after="04-52", entrance="灼熱峽谷 34.80, 85.30", pickup="一般跟線可在安戈洛第二趟結束、回到鐵爐堡後組隊，下站就是燃燒平原。提早在灼熱峽谷組到隊，也可從峽谷南端進黑石山。", pickupS={{"一般跟線可在安戈洛第二趟結束、回到鐵爐堡後組隊，下站就是燃燒平原"}, {"提早在灼熱峽谷組到隊，也可從峽谷南端進黑石山"}}, pickAt="04-45", inst={230}, dq={3801, 3802, 4024, 4083, 4123, 4126, 4128, 4136, 4201, 4241, 4242, 4263, 4264, 4282, 4286, 4295, 4322, 4324, 4341, 4342, 4361, 4362, 4363, 7604, 9015}, supply=nil, danger=nil,
      steps = {
