    [6391] = {races=68, xp=420, items={16310}, d="從獅鷲獸管理員索格拉姆·伯雷森那裡租一隻獅鷲獸飛往鐵爐堡，然後將布洛克的名單交給鐵爐堡的高尼爾·石趾。", n="飛往鐵爐堡", lvl=10, min=10, ps={6387}, fol={6388}},
    [6392] = {races=68, xp=1050, items={16311}, d="從獅鷲獸管理員格萊斯·瑟登那裡租用一頭飛往塞爾薩瑪的獅鷲獸，然後將榮譽鋤交給塞爾薩瑪的布洛克·尋石者。", n="向布洛克回復", lvl=10, min=10, ps={6388}},
    [6603] = {xp=580, d="到冬泉谷的溫泉附近去找到多諾瓦·雪山。", n="冬泉谷的麻煩！", lvl=56, min=52, fol={5082}, chain=true},
    [6604] = {xp=640, d="與墜星村的加隆·石矛談一談。", n="被激怒的梟獸", lvl=59, min=53, fol={4861}},
    [6606] = {xp=660, d="與冬泉谷永望鎮的巫醫瑪艾里談一談。", n="壹點運氣", lvl=60, min=55},
    [6681] = {xp=1950, mob={{0, 0, 1, 0}}, tgo={{"拉文霍德"}}, items={17125}, d="把拉文霍德徽記交給拉文霍德莊園的法拉德，莊園就坐落在希爾斯布萊德的群山之中。\n你的智慧將在這次旅途中得到考驗。做好準備吧。", n="拉文霍德莊園", lvl=24, min=24, fol={6701, 96779, 96781, 96783}},
    [6701] = {mob={{31.1, 1, 2, 0}}, tgo={{"辛迪加刺客", "辛蒂咒術師", "辛迪加劫匪", "辛迪加路霸", "辛迪加雇傭兵", "辛迪加巡路者", "辛迪加潛伏者", "辛迪加間諜"}}, n="辛迪加徽章", lvl=60, min=24, ps={6681}},
    [7383] = {xp=660, mob={{0, 0, 1, 0}}, objs={"神諭林地月井"}, items={18152}, d="用月井的水裝滿紫水晶瓶，然後把它交給多蘭納爾的科瑞薩斯·月怒。", n="大地之冠", lvl=11, min=1, ps={933}, ex={934}, fol={935}},
    [7601] = {d="與費伍德森林的伊普斯談一談。", n="尼比的助手", lvl=50, min=50, fol={7602}},
    [7602] = {xp=5650, mob={{52.8, 1, 2, 0}, {55, 1, 2, 0}, {54.5, 1, 2, 0}}, tgo={{"雷加斯薩特", "雷加斯盜賊", "雷加斯喚魔者", "Legashi Soulstealer", "Legashi Hellraiser", "Legashi Blackguard"}, {"加德納爾軍團士兵"}, {"惡魔守衛哨兵"}}, d="費伍德的伊普斯要求你從三個不同的地區收集三塊無暇的惡魔精華，然後把它們交給他。\n艾薩拉的雷加斯薩特、費伍德森林的加德納爾軍團士兵和詛咒之地的地獄衛士斥候分別擁有一種無暇的惡魔精華。", n="無暇的惡魔精華", lvl=55, min=50, ps={7601}, fol={7603}},
    [7603] = {xp=7050, mob={{55, 0, 1, 1}, {55, 0, 2, 1}}, tgo={{"克羅蘇斯"}, {"克羅蘇斯"}}, items={18626}, d="在費伍德森林的碎痕谷中搜尋克羅蘇斯的屍體。當你找到屍體後，在他身上使用魔火，並等待克羅蘇斯復生。當這個地獄火被喚醒之後，幹掉他，從他的身上拿取克羅蘇斯的惡魔之核。\n把克羅蘇斯的惡魔之核交給費伍德森林的尼比。", n="克羅蘇斯的惡魔之核", lvl=55, min=50, ps={7602}},
    [7701] = {xp=4700, mob={{50, 0, 2, 1}}, tgo={{"工頭瑪托留斯"}}, d="那個叫做工頭瑪托留斯的黑鐵矮人叛徒就藏在大熔爐的熔渣之池深處。\n殺死工頭瑪托留斯，將他的頭顱交給灼熱峽谷的偵查隊長洛洛爾以換取你的獎勵。", n="懸賞：工頭瑪托留斯", lvl=50, min=45, requiredLoot=18946, lootFinishesWork=true, hard=50, soloElite=true},
    [7722] = {xp=4700, mob={{0, 0, 1, 0}}, objs={"秘密設計圖:熾熱助熔劑"}, d="在大熔爐的熔渣之池中的某個地方，你可以找到工頭瑪托留斯偷走的秘密設計圖：熾熱助熔劑。找到這些設計圖，把它們還給灼熱峽谷的大鐵匠博恩奈特。", n="絕密配方！", lvl=50, min=45, requiredLoot=18922, lootFinishesWork=true},
    [7723] = {xp=4550, mob={{48, 20, 1, 0}}, tgo={{"重型作戰傀儡"}}, d="漢瑟爾·重拳讓你殺掉20個重型作戰傀儡。\n重型作戰傀儡就在灼熱峽谷的大熔爐附近。當你殺死足夠多的傀儡後，就回去找漢瑟爾·重拳。", n="該死的胖手指！", lvl=49, min=45},
    [7724] = {xp=4550, mob={{48, 20, 1, 0}}, tgo={{"灼熱熔岩蜘蛛"}}, d="漢瑟爾‧重拳要你殺死灼熱峽谷中的20隻灼熱熔岩蜘蛛。你可以在灼熱峽谷的高地和熔岩池裡找到灼熱熔岩蜘蛛。\n當你殺死足夠的灼熱熔岩蜘蛛之後，回到漢瑟爾‧重拳那裡覆命。", n="熔岩蜘蛛的威脅！", lvl=49, min=45, hard=49},
    [7727] = {xp=4550, mob={{48, 20, 1, 0}}, tgo={{"燻火龍"}}, d="漢瑟爾·重拳要你去殺掉20隻燻火龍。\n燻火龍侵佔了熔渣之池中的那些岩漿池。熔渣之池就在灼熱峽谷的大熔爐中。\n當你殺死足夠數量的燻火龍後，就回到灼熱峽谷找漢瑟爾·重拳。", n="燻火龍", lvl=49, min=45, confirmInteraction=true},
    [7728] = {xp=4400, mob={{46.5, 1, 2, 0}, {47.5, 1, 2, 0}}, tgo={{"黑鐵鍛造師"}, {"黑鐵哨兵"}}, d="找到冶煉鼓風機和偵查員的望遠鏡，把它們還給灼熱峽谷的監工斯克蘭格。\n你所知道的關於這些物品的唯一資訊是：它們肯定是被黑鐵矮人偷走的。冶煉鼓風機是鐵匠用的鍛造工具，偵查員的望遠鏡是偵查員所需的偵查工具。", n="被盜：鼓風機和望遠鏡", lvl=48, min=45},
    [7729] = {xp=4400, mob={{47.5, 15, 1, 0}, {45.5, 15, 1, 0}}, tgo={{"黑鐵監工"}, {"黑鐵奴隸販子"}}, d="殺死15個黑鐵工頭和15個黑鐵奴隸販子。完成任務之後就回去找監工斯克蘭格。", n="工作機會：肅清競爭對手", lvl=48, min=45},
    [7733] = {xp=4400, mob={{47.1, 10, 2, 0}}, tgo={{"狂暴的怒痕雪人", "老年怒痕雪人", "殘忍的怒痕雪人", "潛伏的深痕雪人"}}, d="把10塊怒痕雪人的毛皮交給菲拉斯羽月要塞的普拉特·馬克格魯比。", n="更高的品質", lvl=48, min=40, ps={2821}},
    [7735] = {xp=2200, items={18969}, d="把原始雪人毛皮交給菲拉斯羽月要塞的普拉特·馬克格魯比。", n="原始雪人毛皮", lvl=48, min=40, ps={2821}, cond=true},
    [7791] = {xp=660, mob={{0, 0, 1, 0}}, objs={"奧特蘭克花崗岩", "破爛的箱子", "破損的箱子"}, n="捐獻毛料", lvl=60, min=12},
