    [8151] = {xp=510, d="跟艾薩拉的奧汀克談話。", n="獵人的護符", zt="獵人護符", lvl=52, min=50, fol={8153}},
    [8153] = {xp=5100, mob={{52.5, 1, 2, 0}}, tgo={{"苔蹄快步者"}}, d="將一副完好的苔蹄快步者鹿角交給艾薩拉的奧汀克。奧汀客居住在埃達拉斯廢墟東北部的懸崖頂。", n="苔蹄快步者的鹿角", zt="苔蹄快步者鹿角", lvl=52, min=50, ps={8151}, fol={8231}},
    [8231] = {xp=5100, mob={{52.3, 6, 2, 0}}, tgo={{"幼年碎浪多頭蛇", "碎浪多頭蛇", "大型碎浪多頭蛇"}}, d="將6塊碎浪多頭怪的鱗片交給艾薩拉的奧汀克。奧汀克居住在埃達拉斯廢墟東北部的懸崖頂部。", n="碎浪多頭怪", lvl=52, min=50, ps={8153}, fol={8232}},
    [8232] = {xp=6350, mob={{52, 0, 2, 1}}, tgo={{"摩弗拉斯"}}, d="將摩弗拉斯的牙齒交給艾薩拉的奧汀克。他住在埃達拉斯廢墟東北部懸崖的頂端。", n="神廟中的綠龍", lvl=52, min=50, ps={8231}, hard=52, soloElite=true},
