    [8253] = {xp=6350, mob={{52, 0, 2, 1}}, tgo={{"摩弗拉斯"}}, d="從摩弗拉斯身上取回奧術碎片，然後返回大法師克希雷姆那兒。", n="毀滅摩弗拉斯", lvl=52, min=50, ps={8252}, hard=52, soloElite=true},
    [8254] = {xp=510, d="找到艾薩拉的奧汀克。", n="幫助塞納里奧", zt="塞納裏奧議會的求助", lvl=52, min=50, fol={8255}},
    [8255] = {xp=5100, mob={{52.5, 4, 2, 0}}, tgo={{"苔蹄快步者"}}, d="收集4份健康的野鹿腺體，把它們交給艾薩拉的奧汀克。奧汀克住在埃達拉斯廢墟東北部懸崖的頂部。", n="苔蹄快步者", lvl=52, min=50, ps={8254}, fol={8256}},
    [8256] = {xp=5100, mob={{55.1, 1, 2, 0}}, tgo={{"贊吉爾殭屍", "贊吉爾獵人", "骷髏剝皮者", "骷髏巫士", "恐懼骷髏", "骷髏劊子手", "骷髏督軍", "骷髏侍僧"}}, d="為艾薩拉的奧汀克帶回一份亡靈腐液。奧汀克住在埃達拉斯廢墟東北部懸崖的頂端。", n="亡靈的腐液", lvl=52, min=50, ps={8255}, fol={8257}},
    [8257] = {xp=6350, mob={{52, 0, 2, 1}}, tgo={{"摩弗拉斯"}}, d="前往沉沒的神廟阿塔哈卡，殺死摩弗拉斯，將他的血液交給費伍德森林中的格雷塔·苔蹄。沉沒的神廟的入口就在悲傷沼澤。", n="摩弗拉斯之血", lvl=52, min=50, ps={8256}, hard=52, soloElite=true},
    [8365] = {xp=3900, mob={{45, 1, 2, 0}}, tgo={{"南海海盜", "南海劫掠者", "南海碼頭工人", "南海流氓", "安德雷·費爾比德", "克雷格·尼哈魯"}}, d="塔納利斯熱砂港的傲慢的店主要你去幫他收集20頂南海海盜帽。", n="海盜的帽子！", lvl=45, min=40},
    [8366] = {xp=3900, mob={{44.5, 10, 1, 0}, {44.5, 10, 1, 0}, {44.5, 10, 1, 0}, {44.5, 10, 1, 0}}, tgo={{"南海海盜"}, {"南海劫掠者"}, {"南海碼頭工人"}, {"南海流氓"}}, d="塔納利斯熱砂港的安全主管吉羅姆·比格維茲要你去幹掉10個南海海盜、10個南海劫掠者、10個南海碼頭工人和10個南海流氓。", n="南海復仇", lvl=45, min=40},
    [8414] = {races=5, xp=5100, mob={{55.1, 16, 2, 0}}, tgo={{"骷髏剝皮者", "骷髏巫士", "恐懼骷髏", "骷髏劊子手", "骷髏侍僧", "被奴役的食屍鬼", "腐爛的食屍鬼", "沒有靈魂的食屍鬼"}}, d="收集20個爪牙的天災石，並將它們交給西瘟疫之地的高階牧師賽爾丹尼斯。", n="驅散邪惡", lvl=52, min=50, ps={8415}, fol={8416}},
    [8415] = {races=5, xp=510, d="與冰風崗的指揮官阿什拉姆·瓦羅菲斯特談一談。", n="冰風崗", lvl=52, min=50, fol={8414}, chain=true},
    [8416] = {races=5, xp=2550, items={20612}, d="將惰性天災石交給冰風崗的指揮官阿什拉姆·瓦羅菲斯特。", n="惰性天災石", lvl=52, min=50, ps={8414}, fol={8418}},
    [8417] = {xp=510, d="到詛咒之地的入口去，與部落英雄的靈魂談一談。", n="困擾的靈魂", lvl=50, min=50, fol={8423}},
    [8418] = {races=5, xp=6350, mob={{5025.3, 1, 2, 0}, {5025.5, 1, 2, 0}, {5025, 1, 2, 0}}, tgo={{"加什爾", "祖羅爾", "Gasher", "Zul'Lor"}, {"胡庫", "米杉", "Hukku", "Mijan"}, {"祖羅", "洛若爾", "Loro", "Zolo"}}, d="前往沉沒的神廟，從巨魔守護者們身上取得巫毒羽毛，然後把它們交給阿什拉姆·瓦羅菲斯特。", n="鑄造力量之石", lvl=52, min=50, ps={8416}, hard=52},
    [8420] = {xp=3800, mob={{56.1, 1, 2, 0}}, tgo={{"惡魔獵犬", "惡魔守衛哨兵", "雷加斯薩特", "雷加斯盜賊", "雷加斯喚魔者", "菲達雷德", "碧火盜賊", "碧火欺詐者"}}, d="將一塊惡魔布交給費伍德森林的伊普斯。", n="灼熱的疼痛", lvl=52, min=50, ex={8419}, fol={8421}},
    [8421] = {xp=5100, mob={{53.5, 10, 2, 0}, {51.5, 4, 2, 0}}, tgo={{"鐵木遊蕩者", "鐵木踐踏者", "枯萎的保衛者"}, {"被污染的軟泥怪"}}, d="將10塊腐爛的木頭和4個血毒精華交給費伍德森林的伊普斯。", n="奇怪的材料", lvl=52, min=50, ps={8419, 8420}, fol={8422}},
    [8422] = {xp=6350, mob={{5025.3, 1, 2, 0}, {5025.5, 1, 2, 0}, {5025, 1, 2, 0}}, tgo={{"加什爾", "祖羅爾", "Gasher", "Zul'Lor"}, {"胡庫", "米杉", "Hukku", "Mijan"}, {"祖羅", "洛若爾", "Loro", "Zolo"}}, d="到沉沒的神廟去，從食人妖身上獲得6支巫毒羽毛。", n="巨魔的羽毛", lvl=52, min=50, ps={8421}, hard=52},
    [8423] = {xp=5100, mob={{52.5, 7, 1, 0}}, tgo={{"地獄野豬"}}, d="殺死7頭地獄野豬，然後回到部落英雄的靈魂那兒。", n="戰士的血脈", lvl=52, min=50, hard=53, fol={8424}},
    [8424] = {xp=5100, mob={{52.5, 1, 1, 0}, {51.5, 1, 1, 0}, {52.5, 1, 1, 0}}, tgo={{"影誓專家"}, {"影誓祭司"}, {"影誓暴徒"}}, d="殺死詛咒之地的魔誓者，然後回到部落英雄的靈魂那兒。", n="魔誓者之戰", lvl=52, min=50, ps={8423}, hard=53, fol={8425}},
    [8425] = {xp=6350, mob={{5025.3, 1, 2, 0}, {5025.5, 1, 2, 0}, {5025, 1, 2, 0}}, tgo={{"加什爾", "祖羅爾", "Gasher", "Zul'Lor"}, {"胡庫", "米杉", "Hukku", "Mijan"}, {"祖羅", "洛若爾", "Loro", "Zolo"}}, d="將你從沉沒的神廟的食人妖身上得到的巫毒羽毛交給部落英雄的靈魂。", n="巫毒羽毛", lvl=52, min=50, ps={8424}, hard=52},
